*** Add File: /Volumes/aro/projects/prose_generation/enrichment/bible/work/s103/ehlikitap-images.sol.max.s103-20261009/sec10/root_verdicts.jsonl
+{"root":"ء م ن","decision":"used","hebrew":["אמנ"],"reason":"İbranice אמנ güvenmek, sağlamlaşmak, sadakat ve doğruluk anlamlarını taşır; II. Tarihler 20:20 ile Yeşaya 7:9 aynı kökü inanma ve ayakta kalma için yineler. Arapça ء م ن ile bağı yalnız ses karşılığı düzeyindedir; İbranicedeki işçilik ve bakım yan anlamları bu ayet için kullanılmadı.","paragraphs":[31],"annotations":["S103-TEV-SYD-002"]}
+{"root":"ح ق ق","decision":"used","hebrew":["חקק"],"reason":"İbranice חקק kazımak, hüküm koymak ve belirlenmiş pay anlamlarını kapsar; Sayılar 27:11'de חֻקַּת miras sırasını kanunlaştırır. Arapça haqqın hakikat anlamı bu İbranice hüküm sözcüğünden çıkarılamaz; bağlantı yalnız ses karşılığı ve hukuk bağlamı ile sınırlıdır.","paragraphs":[29],"annotations":["S103-TEV-SYD-001"]}
+{"root":"ص ب ر","decision":"false_friend","hebrew":["צבר"],"reason":"İbranice צבר sekiz yerde yığmak veya yığın anlamındadır (Tekvin 41:35, Mezmur 39:7, Eyüp 27:16 dahil); şerhteki Arapça sabrın sabır, alıkoyma ve kefalet çağrışımlarını taşımaz. Ses karşılığı anlam paraleli kurmaz.","paragraphs":[29,30,31],"annotations":[]}
